  "codes": [
    {
      "label": "Retirement Preparation",
      "quote": "Plans? Just to have a rest, I suppose. Go for a walk in the park in the mornings, do some square dancing with the ladies from our estate, learn to cook a few new dishes."
    },
    {
      "label": "Health Challenges",
      "quote": "My knees haven’t been great these past couple of years. If I push the linen trolley for long they start to hurt, and the doctor has told me to stand less and bend less."
    },
    {
      "label": "Workplace Relationships",
      "quote": "My colleagues all know about it, and every day at work they ask me how many days are left. My team leader says she’ll throw me a farewell party next month."
    },
    {
      "label": "Career Reflection",
      "quote": "Fifteen years of work, it’s about time I had a rest. I know the temper of every machine: which one rattles on the spin cycle, which one needs the temperature turned down two degrees."
    },
    {
      "label": "Family Support",
      "quote": "My daughter finished her master’s the year before last, found a job in Shanghai and rents her own place, so we don’t need to worry about her any more. My husband has been retired for two years."
    },
    {
      "label": "Mentorship Role",
      "quote": "The new people all come and ask me. Last winter that tumble dryer broke down, and the Engineering people spent two days on it without fixing it. In the end I was the one who found the fault, just by the sound."
    }
  ],
  "interpretation": "The interviewee is reflecting on her 15-year career, preparing for retirement while balancing health challenges, family support, and workplace relationships, with a mix of nostalgia and anticipation for her next chapter.",
  "tone": "mixed",
  "confidence": 85
}

